import React, { useEffect } from 'react';
import {useState} from 'react'
const LoginPage = () => {
const[name,setName]=useState("");
const[email,setEmail]=useState("");
const[phone,setPhone]=useState(0);
const[age,setAge]=useState(0);
const[password,setPassword]=useState("");





    const submit=(e)=>{
        e.preventDefault()
        setName(e.target.name.value);
        setEmail(e.target.email.value);
        setPhone(e.target.phone.value);
        setAge(e.target.age.value);
        setPassword(e.target.password.value);
    }

    const userdetails={name,email,phone,age,password};
    try{
    const api="http://localhost:5500/employees/add-employee"
    const res= async ()=>
        {
            await fetch(api,
              { method:"POST",
                headers:{
               "Content-Type":'Application/json'},
               body:JSON.stringify(userdetails)})
        }
        
    }catch(error){
        console.log("error to submit")
    }
    
  return (
    <div>
      <div>
        <form onSubmit={submit}>
            <label>UserName</label>
            <input type="text" name="name" placeholder='Username'/><br />
            <label>Email</label>
            <input type="email"name="email" placeholder='Email'/><br />
            <label>Phone</label>
            <input type="tel"name="phone" placeholder='PhoneNumber'/><br />
            <label>age</label>
            <input type="number"name="age" placeholder='age'/><br />
            <label>Password</label>
            <input type="text" name="password" placeholder='Password'/><br />
            <button type='submit'>Submit</button>
        </form>
      </div>
      <div>
            
      </div>
    </div>
  );
}

export default LoginPage;
